const prompt = $('Get Channel Prompt').first().json.data;
const ctx = $('Prepare Get-Prompt Input').first().json._ctx;
const sources = $('Get Project Sources').first().json.sources;
const claims = $('Get Project Claims').first().json;
const model = (prompt.model_compatibility && prompt.model_compatibility[0]) || 'claude-opus-4-8';
const userPayload = { topic: ctx.topic, sources, claims };
const schema = {"title":"Research Package Synthesis","description":"Structured output of the research-package-synthesis LLM call — the JSONB stored in research_packages.synthesis. Narrative/analytical fields only: claim and source listings are never duplicated here — they are assembled live from the relational tables by get_current_research_package() at read time, so there is exactly one source of truth. `cited_source_ids` must list every source_id referenced anywhere in this document; build_research_package() rejects the package (CITATION_INTEGRITY_FAILED) if any id is not a real source_id for this project. See docs/architecture/research-pipeline.md#research-package.","type":"object","additionalProperties":false,"required":["project_summary","research_question","important_statistics","chronology","open_questions","research_gaps","suggested_script_angles","prohibited_unsafe_assertions","cited_source_ids"],"properties":{"project_summary":{"type":"string"},"research_question":{"type":"string"},"important_statistics":{"type":"array","items":{"type":"object","additionalProperties":false,"required":["statistic","source_ids"],"properties":{"statistic":{"type":"string"},"source_ids":{"type":"array","items":{"type":"string"},"minItems":1}}}},"chronology":{"type":"array","description":"Timeline entries, only where the topic is reasonably chronological — empty array otherwise.","items":{"type":"object","additionalProperties":false,"required":["event","source_ids"],"properties":{"date_or_period":{"type":["string","null"]},"event":{"type":"string"},"source_ids":{"type":"array","items":{"type":"string"}}}}},"open_questions":{"type":"array","items":{"type":"string"}},"research_gaps":{"type":"array","items":{"type":"string"}},"suggested_script_angles":{"type":"array","items":{"type":"string"}},"prohibited_unsafe_assertions":{"type":"array","description":"Assertions the collected research does NOT support and the future script must not make.","items":{"type":"string"}},"cited_source_ids":{"type":"array","description":"Union of every source_id cited anywhere in this document (important_statistics[].source_ids, chronology[].source_ids, and any inline citation elsewhere). Checked against `sources` by validate_research_package_citations() — never trusted as-is.","items":{"type":"string"}}}};
return [{ json: {
  ctx, model,
  requestBody: {
    model, max_tokens: 8192,
    system: prompt.content,
    messages: [{ role: 'user', content: JSON.stringify(userPayload) }],
    output_config: { format: { type: 'json_schema', schema } }
  }
} }];

const resp = $input.first().json;
const ctx = $('Prepare Anthropic Request (initial)').first().json.ctx;
const model = $('Prepare Anthropic Request (initial)').first().json.model;
const textBlock = (resp.content || []).find((b) => b.type === 'text');
let synthesis = null; let parse_failed = true;
if (textBlock) { try { synthesis = JSON.parse(textBlock.text); parse_failed = false; } catch (e) { parse_failed = true; } }
return [{ json: { parse_failed, ctx, model, synthesis, usage: resp.usage || {}, provider_request_id: resp.id || null } }];

const ctx = $json.ctx;
return [{ json: {
  success: false, data: null,
  error: { code: 'RESEARCH_QC_FAILED', message: 'research package synthesis LLM response was not valid structured JSON after retries', retryable: true, error_id: null },
  runtime: { channel_id: ctx.channel_id, workflow_run_id: ctx.workflow_run_id, content_project_id: ctx.content_project_id, correlation_id: null }
} }];

const j = $('Parse Package Response (initial)').first().json; const ctx = j.ctx;
// Pricing: $5.00 / 1M input tokens, $25.00 / 1M output tokens.
// One multiply-and-divide per call, not a compounding ledger -- every
// persistent aggregate (SUM() over cost_events.total_cost_usd, a NUMERIC
// column) happens in SQL, never in JS. See
// docs/architecture/research-pipeline.md#cost-tracking.
const inputTokens = j.usage.input_tokens || 0;
const outputTokens = j.usage.output_tokens || 0;
const inputCost = (inputTokens / 1000000) * 5;
const outputCost = (outputTokens / 1000000) * 25;
const totalCost = Math.round((inputCost + outputCost) * 1000000) / 1000000;
return [{ json: {
  channel_id: ctx.channel_id, content_project_id: ctx.content_project_id, workflow_run_id: ctx.workflow_run_id, workflow_step_id: null,
  provider: 'anthropic', service_type: 'llm', model: j.model,
  quantity: inputTokens + outputTokens, unit: 'token', unit_price_usd: null,
  total_cost_usd: totalCost, provider_request_id: j.provider_request_id, estimated: false, metadata: {}
} }];

const j = $('Parse Package Response (initial)').first().json; const ctx = j.ctx;
return [{ json: {
  channel_id: ctx.channel_id, workflow_run_id: ctx.workflow_run_id, content_project_id: ctx.content_project_id,
  research_plan_id: ctx.research_plan_id || null, synthesis: j.synthesis, provider: 'anthropic', model: j.model,
  revision_trigger: 'initial', revision_reason: ctx.revision_reason || null
} }];

const ctx = $('Parse Package Response (initial)').first().json.ctx;
const pkg = $json.data;
return [{ json: { channel_id: ctx.channel_id, workflow_run_id: ctx.workflow_run_id, content_project_id: ctx.content_project_id, research_package_id: pkg.research_package_id, _package: pkg } }];

const ctx = $('Prepare QC Input (initial)').first().json;
return [{ json: {
